import type { CSSProperties } from "react";

const nodes = ["Diesel Engine", "Generator", "Power Distribution", "Motor", "Track", "Mission"];

export function PowerFlow() {
  return (
    <div className="power-flow" aria-label="Animated power flow diagram">
      <div className="flow-grid" />
      <div className="energy-line" />
      {nodes.map((node, index) => (
        <div className="flow-node" style={{ "--i": index } as CSSProperties} key={node}>
          <span className="node-index">0{index + 1}</span>
          <strong>{node}</strong>
        </div>
      ))}
      <div className="pulse pulse-a" /><div className="pulse pulse-b" /><div className="pulse pulse-c" />
      <p className="flow-caption">ENERGY → MOTION → MISSION</p>
    </div>
  );
}
